using System.Text.Json;

using EvTrainer.Web.Domain.Model;

namespace EvTrainer.Web.Domain.Reference;

/// <summary>Species #1–386 with Generation III base stats [HP, Ataque, Defesa, SpAtk, SpDef, Speed].</summary>
public sealed record PokedexSpecies(int Dex, string Name, int[] Base, int? EvolvesFrom)
{
    public SpeciesEntry ToEntry() => new() { Name = Name, Base = [.. Base] };
}

/// <summary>Embedded Gen III Pokédex (pokedex-gen3.json, generated by scripts/BuildPokedex.cs).</summary>
public sealed class Pokedex
{
    private const string ResourceName = "EvTrainer.pokedex-gen3.json";
    private const int MaxLine = 3;

    private readonly Dictionary<string, PokedexSpecies> _byName;
    private readonly Dictionary<int, PokedexSpecies> _byDex;
    private readonly ILookup<int, PokedexSpecies> _children;
    private readonly IReadOnlyList<(PokedexSpecies Species, string Folded)> _index;

    private Pokedex(IReadOnlyList<PokedexSpecies> species)
    {
        Species = species;
        _byName = species.ToDictionary(s => s.Name, StringComparer.OrdinalIgnoreCase);
        _byDex = species.ToDictionary(s => s.Dex);
        _children = species.Where(s => s.EvolvesFrom is not null).ToLookup(s => s.EvolvesFrom!.Value);
        _index = [.. species.Select(s => (s, TextFold.Fold(s.Name)))];
    }

    public IReadOnlyList<PokedexSpecies> Species { get; }

    public static Pokedex LoadEmbedded()
    {
        using var stream = typeof(Pokedex).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource '{ResourceName}' not found.");
        using var document = JsonDocument.Parse(stream);
        return new Pokedex(
        [
            .. document.RootElement.GetProperty("species").EnumerateArray().Select(s => new PokedexSpecies(
                s.GetProperty("dex").GetInt32(),
                s.GetProperty("name").GetString()!,
                [.. s.GetProperty("base").EnumerateArray().Select(v => v.GetInt32())],
                s.GetProperty("evolvesFrom").ValueKind == JsonValueKind.Number ? s.GetProperty("evolvesFrom").GetInt32() : null)),
        ]);
    }

    public PokedexSpecies? Find(string name) => _byName.GetValueOrDefault(name.Trim());

    /// <summary>Species by name (accents and case ignored) or Pokédex number; exact matches first, then prefixes.</summary>
    public IReadOnlyList<PokedexSpecies> Search(string query, int max = 8)
    {
        var folded = TextFold.Fold(query.Trim()).TrimStart('#');
        if (folded.Length == 0)
        {
            return [];
        }

        if (int.TryParse(folded, out var number))
        {
            return _byDex.TryGetValue(number, out var exact) ? [exact] : [];
        }

        return
        [
            .. _index
                .Where(e => e.Folded.Contains(folded, StringComparison.Ordinal))
                .OrderBy(e => e.Folded == folded ? 0 : e.Folded.StartsWith(folded, StringComparison.Ordinal) ? 1 : 2)
                .ThenBy(e => e.Species.Dex)
                .Take(max)
                .Select(e => e.Species),
        ];
    }

    public IReadOnlyList<PokedexSpecies> EvolutionsOf(PokedexSpecies species) => [.. _children[species.Dex]];

    /// <summary>
    /// Evolution line through <paramref name="species"/>: all its ancestors, itself and the following
    /// evolutions while there is a single option (branches are chosen by the user). At most 3 species.
    /// </summary>
    public IReadOnlyList<PokedexSpecies> LineFor(PokedexSpecies species)
    {
        List<PokedexSpecies> line = [species];
        for (var current = species; current.EvolvesFrom is { } parent && _byDex.TryGetValue(parent, out var previous); current = previous)
        {
            line.Insert(0, previous);
        }

        for (var current = species; line.Count < MaxLine && EvolutionsOf(current) is [var only];)
        {
            line.Add(only);
            current = only;
        }

        return line;
    }
}